package com.hbm.machine.excavator;
import com.hbm.multiblock.DummyableBlock;import com.mojang.serialization.MapCodec;import java.util.*;import net.minecraft.core.*;import net.minecraft.world.entity.LivingEntity;import net.minecraft.world.item.ItemStack;import net.minecraft.world.item.context.BlockPlaceContext;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.SoundType;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.level.material.MapColor;
/** Original union of the7x7head and three lower foot rectangles, validated before any placement. */
public final class ExcavatorBlock extends DummyableBlock {
 private static final int[][] DIM={{3,0,3,3,3,3},{-1,3,3,-2,3,-2},{-1,3,3,-2,-2,3},{-1,3,-2,3,3,3}};
 public ExcavatorBlock(){super(Properties.of().mapColor(MapColor.METAL).strength(5,60).sound(SoundType.STONE).requiresCorrectToolForDrops().noOcclusion());}@Override protected MapCodec<? extends DummyableBlock> codec(){return MapCodec.unit(this);}@Override public int[] dimensions(){return DIM[0].clone();}@Override public int offset(){return 3;}@Override public int heightOffset(){return 3;}
 private static Set<BlockPos> cells(BlockPos core,Direction facing){var cells=new LinkedHashSet<BlockPos>();for(var raw:DIM){var d=rotate(raw,facing);for(var p:BlockPos.betweenClosed(core.offset(-d[4],-d[1],-d[2]),core.offset(d[5],d[0],d[3])))cells.add(p.immutable());}return cells;}
 @Override public BlockState getStateForPlacement(BlockPlaceContext context){var core=coreForPlacement(context);var facing=context.getHorizontalDirection().getOpposite();for(var p:cells(core,facing)){if(!context.getLevel().isInWorldBounds(p)||!context.getLevel().hasChunkAt(p)||!p.equals(context.getClickedPos())&&!context.getLevel().getBlockState(p).canBeReplaced())return null;}return super.getStateForPlacement(context);}
 @Override public void setPlacedBy(Level level,BlockPos pos,BlockState state,LivingEntity placer,ItemStack stack){super.setPlacedBy(level,pos,state,placer,stack);if(level.isClientSide)return;var facing=placementFacing(state);var core=pos.above(heightOffset()).relative(facing,-offset());safely(()->{for(var p:cells(core,facing)){if(p.getY()>=core.getY())continue;level.setBlock(p,defaultBlockState().setValue(LEGACY_META,Direction.DOWN.get3DDataValue()),UPDATE_ALL);}for(var port:ExcavatorBlockEntity.ports(core,facing))setPort(level,port.pos(),true);});}
 @Override public BlockEntity newBlockEntity(BlockPos pos,BlockState state){return isCore(state)?new ExcavatorBlockEntity(pos,state):isPort(state)?new ExcavatorPort(pos,state):null;}@Override public <T extends BlockEntity> BlockEntityTicker<T> getTicker(Level level,BlockState state,BlockEntityType<T> type){return isCore(state)?createTickerHelper(type,ExcavatorContent.ENTITY.get(),ExcavatorBlockEntity::tick):null;}
}
